#nullable enable
using Microsoft.AspNetCore.Mvc; using Modular.Modules.Contracts; using Modular.Modules.ModuleManagement.Application;
namespace Modular.Modules.ModuleManagement.Controllers;
[Route("admin/modules")] public sealed class ModulesController:Controller { readonly ModuleManagementService service; public ModulesController(ModuleManagementService s)=>service=s; [HttpGet("")]public IActionResult Index()=>View(service.List()); [HttpGet("create")]public IActionResult Create()=>View(new ModuleInput("","","1.0.0","",ModuleKind.Feature,Array.Empty<string>())); [HttpPost("create"),ValidateAntiForgeryToken]public IActionResult Create(ModuleInput x)=>Save(x,"Create"); [HttpGet("{id}/edit")]public IActionResult Edit(string id)=>service.Get(id) is{} m?View(ToInput(m)):NotFound(); [HttpPost("{id}/edit"),ValidateAntiForgeryToken]public IActionResult Edit(string id,ModuleInput x)=>string.Equals(id,x.Id,StringComparison.OrdinalIgnoreCase)?Save(x,"Edit"):BadRequest(); [HttpGet("{id}")]public IActionResult Details(string id)=>service.Get(id) is{} m?View(m):NotFound(); [HttpPost("{id}/enable"),ValidateAntiForgeryToken]public IActionResult Enable(string id)=>Change(id,true); [HttpPost("{id}/disable"),ValidateAntiForgeryToken]public IActionResult Disable(string id)=>Change(id,false); [HttpPost("{id}/delete"),ValidateAntiForgeryToken]public IActionResult Delete(string id)=>service.Delete(id)?RedirectToAction(nameof(Index)):NotFound(); IActionResult Save(ModuleInput x,string v){var r=service.Save(x);if(!r.Succeeded){foreach(var e in r.Errors)ModelState.AddModelError("",e);return View(v,x);}return RedirectToAction(nameof(Details),new{id=x.Id});} IActionResult Change(string id,bool on){var r=service.SetEnabled(id,on);if(!r.Succeeded)TempData["Error"]=string.Join(" ",r.Errors);return RedirectToAction(nameof(Index));} static ModuleInput ToInput(ModuleRecord x)=>new(x.Id,x.Name,x.Version,x.Description,x.Kind,x.Dependencies); }
